  "revision_action": "keep",
  "supportive_card_ids": ["C18","C24","C02","C22","C25","C28","C33","C10","C21","C08","C23","C73","C79","C77"],
  "contradictory_card_ids": ["C09","C31","C36","C75"],
  "prediction_basis_card_ids": ["C18","C24","C02","C22","C25","C28","C33","C10","C21","C08","C23","C73","C79","C77"],
  "claims": [
    {
      "claim": "Direct human F measurements for structurally related polar polycyclic lactones are at or above 20%: DHA 45% (95% CI 34-56), etoposide 38-52% and 48±18%, 9-AC 27-49%, and hydrocortisone 56-96%.",
      "card_ids": ["C18","C24","C02","C22","C25","C28","C33","C10","C21","C08","C23"]
    },
    {
      "claim": "Bilobalide, the closest terpene-trilactone analog, shows moderate Caco-2 absorptive Papp (4.96±0.12 ×10^-6 cm/s) with no significant efflux (secretory 5.31±0.02 ×10^-6 cm/s), supporting intestinal absorption rather than gut-wall loss.",
      "card_ids": ["C73","C79","C77"]
    },
    {
      "claim": "L6 hepatic-clearance records are for other molecules (triptolide, artemisinin, simvastatin, macrolides, cortisol) and do not provide query-specific presystemic-loss evidence; where corresponding oral F is known (erythromycin 25-36%, hydrocortisone 56-96%), measurable clearance did not reduce F below 20%.",
      "card_ids": ["C83","C85","C90","C86","C91","C92","C84","C20","C05","C08","C23"]
    },
    {
      "claim": "The low-F L1 records are not transferable to the query: omadacycline 0.6% was measured 4 h after a high-fat meal, CGP 43371 9% is a different chemotype, and moxidectin 10.6% is an alpaca relative-F value versus SC.",
      "card_ids": ["C09","C31","C36"]
    },
    {
      "claim": "No affirmative threshold-relevant evidence supports F < 20% for the query; the 9-NC Caco-2 Papp below 1e-5 cm/s (C75) is less structurally relevant, and the 9-AC context shows oral F 27-49% despite similar solubility/permeability limitations.",
      "card_ids": ["C75","C10","C21"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C83","C84","C85","C86","C87","C88","C89","C90","C91","C92","C93","C94"]
    }
  ],
  "evidence_gaps": [
    "No direct human or animal absolute oral bioavailability measurement for the query molecule (ginkgolide-type terpene trilactone).",
    "No matched oral versus IV exposure data for the query.",
    "No ginkgolide-specific hepatic clearance or metabolic stability data; L6 records are for triptolide, artemisinin, simvastatin, macrolides, and cortisol.",
    "Query CYP/esterase metabolism and lactone stability are unknown.",
    "Query logD -1.37 and TPSA 148.8 remain unresolved permeability concerns.",
    "No ginkgolide-specific Caco-2 permeability, efflux, or intestinal metabolism data; only bilobalide as a close structural analog."
  ],
  "decision_summary": "L6 provides no query-specific hepatic clearance or metabolic stability data; its records for other terpene lactones and known-F drugs do not affirmatively establish F < 20% for the query. Direct human F values for related polar polycyclic lactones and bilobalide permeability/efflux data continue to make F >= 20% better supported, so prediction remains high with low confidence."
}

